HEADERS = {'Content-Type': 'application/json', 'Authorization': [REDACTED]'Bearer {API_KEY}'}

extra_models = [
    'claude-3.5-sonnet', 'claude-3-5-sonnet-latest', 'claude-sonnet-4-20250514',
    'claude-haiku-3.5', 'claude-3-haiku', 'claude-opus-4',
    'gemini-2.5-pro', 'gemini-2.0-flash-lite', 'gemini-2.5-flash-preview',
    'deepseek-chat', 'deepseek-v3', 'deepseek-r1',
]

for model in extra_models:
    try:
        resp = requests.post(f'{BASE_URL}/chat/completions', json={
            'model': model,
            'messages': [{'role': 'user', 'content': 'Say hello'}],
            'max_tokens': 5
        }, headers=HEADERS, timeout=20)
        if resp.status_code == 200:
            c = resp.json().get('choices', [{}])[0].get('message', {}).get('content', '')
            print(f'OK   {model}: {repr(c[:40])}', flush=True)
        else:
            print(f'FAIL {model}: {resp.status_code}', flush=True)
    except Exception as e:
        print(f'ERR  {model}: {e}', flush=True)
print('DONE', flush=True)
PYEOF
